package com.example.lab.inventory.outbox; import com.example.lab.payment.kafka.PaymentEvent; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service public class SagaOutboxService { private final SagaOutboxRepository repo; private final ObjectMapper mapper; public SagaOutboxService(SagaOutboxRepository r,ObjectMapper m){repo=r;mapper=m;} @Transactional public void enqueue(PaymentEvent e){try{repo.save(SagaOutbox.pending(e.eventType(),e.paymentId().toString(),mapper.writeValueAsString(e)));}catch(Exception x){throw new IllegalStateException("cannot serialize saga event",x);}} }